complex_function() {
    local param1="$1"
    local param2="${2:-default}"
    local param3="$(printf '%s' "$3" | sed -e 's#\\"#\\\\\\"#g')"
    printf '%s\n' "Param1: $param1"
    printf '%s\n' "Param2: $param2"
    printf '%s\n' "Param3: $param3"
    local result=$(printf '%s\n' "$param1" | sed s/old/new/g)
    printf '%s\n' "Result: $result"
}
