printf '%s\n' "First item: "${array_0}""
test_locals() {
    local var1="$1"
    local var2="${2:-default_value}"
    local var3="$(printf '%s\n' "$var1" | tr '[:lower:]' '[:upper:]')"
    printf '%s\n' "Var1: $var1"
    printf '%s\n' "Var2: $var2"
    printf '%s\n' "Var3: $var3"
}
